head.script:
scwin.checkBeforeTime = function() {
    date = new Date();
    min = date.getMinutes();
    sec = date.getSeconds();
    milisec = date.getMilliseconds();
    before = (min * 60 + sec) * 1000 + milisec;
}
scwin.checkAfterTime = function() {
    date = new Date();
    min = date.getMinutes();
    sec = date.getSeconds();
    milisec = date.getMilliseconds();
    after = (min * 60 + sec) * 1000 + milisec;
}
scwin.compareTime = function() {
    return Math.abs(after - before) <= 200;
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "1500");
    WebSquare.wUnit.addCommand("set", "scwin.checkBeforeTime()");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById($p.id+'grid1_column3').children[0].click()");
    WebSquare.wUnit.addCommand("set", "scwin.checkAfterTime()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.compareTime()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.checkBeforeTime()");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById($p.id+'grid1_column3').children[0].click()");
    WebSquare.wUnit.addCommand("set", "scwin.checkAfterTime()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.compareTime()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    grid1.setRef({
        ref: "root/ui/vector"
    });
    var date, min, sec, milisec, before, after;
    window.date = undefined;
    window.min = undefined;
    window.sec = undefined;
    window.milisec = undefined;
    window.before = undefined;
    window.after = undefined;
    //Created By: Sangwook
    //Created By: 2020.11.24
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
